async function compressShopImage(file, maxSide){
  if(!file)return '';
  if(file.size>15*1024*1024)throw new Error('اختر صورة حجمها أقل من 15 ميغابايت');
  if(!file.type.startsWith('image/'))throw new Error('اختر ملف صورة صالحًا');
  const image=await createImageBitmap(file),scale=Math.min(1,maxSide/Math.max(image.width,image.height)),canvas=document.createElement('canvas');
  canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();
  const data=canvas.toDataURL('image/webp',.82);if(data.length>1_400_000)throw new Error('حجم الصورة بعد الضغط كبير؛ اختر صورة أصغر');return data;
}
