    const {order,shop}=await api(`/api/public/orders/${encodeURIComponent(id)}${orderDesignLoaded?'':'?design=1'}`);orderDesignLoaded=true;
    document.body.className=`customer-page ${themeClass(shop.theme)}`;
    const colorProperties={surface:'--customer-card-surface',text:'--customer-card-text',accent:'--customer-card-accent',border:'--customer-card-border'};
    for(const [key,property] of Object.entries(colorProperties))if(/^#[0-9a-f]{6}$/i.test(shop.cardColors?.[key]||''))document.documentElement.style.setProperty(property,shop.cardColors[key]);
    const cardStyle=shop.cardStyle||{};if(Number.isInteger(cardStyle.width)&&cardStyle.width>=320&&cardStyle.width<=520)document.documentElement.style.setProperty('--customer-card-width',`${cardStyle.width}px`);if(Number.isInteger(cardStyle.height)&&cardStyle.height>=480&&cardStyle.height<=800)document.documentElement.style.setProperty('--customer-card-height',`${cardStyle.height}px`);if(Number.isInteger(cardStyle.width)&&Number.isInteger(cardStyle.height))document.documentElement.style.setProperty('--customer-card-ratio',String(cardStyle.width/cardStyle.height));if(Number.isInteger(cardStyle.radius)&&cardStyle.radius>=14&&cardStyle.radius<=40)document.documentElement.style.setProperty('--customer-card-radius',`${cardStyle.radius}px`);if(Number.isInteger(cardStyle.scale)&&cardStyle.scale>=90&&cardStyle.scale<=115)document.documentElement.style.setProperty('--customer-card-scale',String(cardStyle.scale/100));if(Number.isInteger(cardStyle.shadow)&&cardStyle.shadow>=0&&cardStyle.shadow<=30)document.documentElement.style.setProperty('--customer-card-shadow',`${cardStyle.shadow}%`);
    const mark=document.querySelector('.customer-ticket-brand .brand-mark');if(mark&&shop.iconImage){const logo=document.createElement('img');logo.className='customer-shop-icon';logo.src=shop.iconImage;logo.alt='';mark.replaceWith(logo);}
    const orderLogo=document.getElementById('orderShopLogo'),logoFallback=document.getElementById('orderShopLogoFallback');document.getElementById('orderShopLogoFrame').setAttribute('aria-label',`شعار ${shop.name}`);logoFallback.textContent=String(shop.name||brandCopy.brandMark).trim().slice(0,1)||brandCopy.brandMark;if(shop.iconImage){orderLogo.src=shop.iconImage;orderLogo.alt=shop.name;orderLogo.classList.remove('hidden');logoFallback.classList.add('hidden');}
    document.getElementById('orderShop').textContent=shop.name;
    document.getElementById('orderNumber').textContent=order.number;
    document.getElementById('orderStatus').textContent=order.statusLabel;
    document.getElementById('orderCustomer').textContent=order.customerName?`باسم: ${order.customerName}`:'';
    document.getElementById('orderItem').textContent=order.item;
    document.getElementById('prepEstimate').textContent=order.prepMinutes?`المدة التقديرية: ${order.prepMinutes} دقائق`:'';
    const currentStep=orderStates.indexOf(order.status);document.querySelectorAll('[data-progress]').forEach(el=>{const step=orderStates.indexOf(el.dataset.progress);el.classList.toggle('done',step>=0&&step<currentStep);el.classList.toggle('current',step===currentStep);});
    const review=document.getElementById('reviewBtn');if(order.status==='completed'&&shop.reviewUrl){review.href=shop.reviewUrl;review.classList.remove('hidden');}
